//modified from https://www.shadertoy.com/view/wtlcR8
void mainImage(out vec4 O, vec2 U) {
    vec3 c1 = vec3(0.98, 0.20, 0.72);
    vec3 c2 = vec3(0.64, 0.23, 0.57);
    vec3 c3 = vec3(0.25, 0.47, 0.46);

    int x = int(U),
    y = int(U.y + 20. * iTime),
    r = (x)^(y);

    vec4 l = vec4(abs(r*r*r)/(y+int(iTime*50.)) % 10970 < 1000);

    vec2 xy = U.xy / iResolution.xy;
    float h = 0.5;
    O = vec4(mix(vec3(0.0, 0.0, 0.0), mix(mix(c1, c2, xy.x/h), mix(c2, c3, (xy.x - h)/(1.0 - h)), step(h, xy.x)), l.x), 0.0);
}

